S = 2 * T
# Tile positions (top-left corner coordinates)
tile_positions = [
    (T//2, T//2),        # (26, 26)
    (T//2, T + T//2),    # (26, 78)
    (T + T//2, T//2),    # (78, 26)
    (T + T//2, T + T//2) # (78, 78)
]
N = len(tile_positions)

# Initialize the coverage grid
coverage = [[0 for _ in range(S)] for _ in range(S)]

# Apply tiles
for r_start, c_start in tile_positions:
    for r in range(r_start, r_start + T):
        for c in range(c_start, c_start + T):
            # Ensure coordinates are within the 2T x 2T bounds (should be automatically true here, but good practice)
            if 0 <= r < S and 0 <= c < S:
                coverage[r][c] += 1

# Calculate frequency distribution of non-zero counts
frequency = {}
for r in range(S):
    for c in range(S):
        count = coverage[r][c]
        if count > 0:
            frequency[count] = frequency.get(count, 0) + 1

# Find k (the maximum frequency)
if not frequency:
    k = 0
else:
    k = max(frequency.values())

print(f"Total cells analyzed: {S*S}")
print(f"Frequency distribution (Count: Frequency): {frequency}")
print(f"Largest frequency k: {k}")

